     9→import Combine
    10→import Foundation
    11→import MatrixRustSDK
    12→import OrderedCollections
    13→import SwiftUI
    14→
    15→typealias RoomScreenViewModelType = StateStoreViewModel<RoomScreenViewState, RoomScreenViewAction>
    16→
    17→class RoomScreenViewModel: RoomScreenViewModelType, RoomScreenViewModelProtocol {
    18→    private let clientProxy: ClientProxyProtocol
    19→    private let roomProxy: JoinedRoomProxyProtocol
    20→    private let appSettings: AppSettings
    21→    private let analyticsService: AnalyticsService
    22→    private let userIndicatorController: UserIndicatorControllerProtocol
    23→    
    24→    private var initialSelectedPinnedEventID: String?
    25→    private let pinnedEventStringBuilder: RoomEventStringBuilder
    26→    
    27→    private var identityPinningViolations = [String: RoomMemberProxyProtocol]()
    28→    private var identityVerificationViolations = [String: RoomMemberProxyProtocol]()
    29→    
    30→    private let actionsSubject: PassthroughSubject<RoomScreenViewModelAction, Never> = .init()
    31→    var actions: AnyPublisher<RoomScreenViewModelAction, Never> {
    32→        actionsSubject.eraseToAnyPublisher()
    33→    }
    34→    
    35→    private var pinnedEventsTimelineItemProvider: TimelineItemProviderProtocol? {
    36→        didSet {
    37→            guard let pinnedEventsTimelineItemProvider else {
    38→                return
    39→            }
    40→            
    41→            buildPinnedEventContents(timelineItems: pinnedEventsTimelineItemProvider.itemProxies)
    42→            pinnedEventsTimelineItemProvider.updatePublisher
    43→                // When pinning or unpinning an item, the timeline might return empty for a short while, so we need to debounce it to prevent weird UI behaviours like the banner disappearing
    44→                .debounce(for: .milliseconds(100), scheduler: DispatchQueue.main)
    45→                .sink { [weak self] updatedItems, _ in
    46→                    guard let self else { return }
    47→                    buildPinnedEventContents(timelineItems: updatedItems)
    48→                }
    49→                .store(in: &cancellables)
    50→        }
    51→    }
    52→    
    53→    init(userSession: UserSessionProtocol,
    54→         roomProxy: JoinedRoomProxyProtocol,
    55→         initialSelectedPinnedEventID: String?,
    56→         ongoingCallRoomIDPublisher: CurrentValuePublisher<String?, Never>,
    57→         appSettings: AppSettings,
    58→         appHooks: AppHooks,
    59→         analyticsService: AnalyticsService,
    60→         userIndicatorController: UserIndicatorControllerProtocol) {
    61→        clientProxy = userSession.clientProxy
    62→        self.roomProxy = roomProxy
    63→        self.appSettings = appSettings
    64→        self.analyticsService = analyticsService
    65→        self.userIndicatorController = userIndicatorController
    66→        
    67→        self.initialSelectedPinnedEventID = initialSelectedPinnedEventID
    68→        pinnedEventStringBuilder = .pinnedEventStringBuilder(userID: roomProxy.ownUserID)
    69→
    70→        let roomHistorySharingState: RoomHistorySharingState? = if appSettings.enableKeyShareOnInvite {
    71→            roomProxy.infoPublisher.value.historySharingState
    72→        } else {
    73→            nil
    74→        }
    75→        
    76→        let viewState = RoomScreenViewState(roomTitle: roomProxy.infoPublisher.value.displayName ?? roomProxy.id,
    77→                                            roomAvatar: roomProxy.infoPublisher.value.avatar,
    78→                                            hasOngoingCall: roomProxy.infoPublisher.value.hasRoomCall,
    79→                                            hasSuccessor: roomProxy.infoPublisher.value.successor != nil,
    80→                                            roomHistorySharingState: roomHistorySharingState)
    81→        super.init(initialViewState: appHooks.roomScreenHook.update(viewState),
    82→                   mediaProvider: userSession.mediaProvider)
    83→        
    84→        updateRoomInfo(roomProxy.infoPublisher.value)
    85→        setupSubscriptions(ongoingCallRoomIDPublisher: ongoingCallRoomIDPublisher)
    86→        
    87→        Task {
    88→            await updateVerificationBadge()
    89→        }
    90→    }
    91→
    92→    override func process(viewAction: RoomScreenViewAction) {
    93→        switch viewAction {
    94→        case .tappedPinnedEventsBanner:
    95→            handleTappedPinnedEventsBanner()
    96→        case .viewAllPins:
    97→            analyticsService.trackInteraction(name: .PinnedMessageBannerViewAllButton)
    98→            actionsSubject.send(.displayPinnedEventsTimeline)
    99→        case .displayRoomDetails:
   100→            actionsSubject.send(.displayRoomDetails)
   101→        case .displayCall:
   102→            actionsSubject.send(.displayCall)
   103→            actionsSubject.send(.removeComposerFocus)
   104→            analyticsService.trackInteraction(name: .MobileRoomCallButton)
   105→        case .footerViewAction(let action):
   106→            switch action {
   107→            case .resolvePinViolation(let userID):
   108→                Task { await resolveIdentityPinningViolation(userID) }
   109→            case .resolveVerificationViolation(let userID):
   110→                Task { await resolveIdentityVerificationViolation(userID) }
   111→            }
   112→        case .acceptKnock(let eventID):
   113→            Task { await acceptKnock(eventID: eventID) }
   114→        case .dismissKnockRequests:
   115→            Task { await markAllKnocksAsSeen() }
   116→        case .viewKnockRequests:
   117→            actionsSubject.send(.displayKnockRequests)
   118→        case .displaySuccessorRoom:
   119→            guard let successorID = roomProxy.infoPublisher.value.successor?.roomId else { return }
   120→            let serverNames = roomProxy.knownServerNames(maxCount: 50) // Limit to the same number used by ClientProxy.resolveRoomAlias(_:)
   121→            actionsSubject.send(.displayRoom(roomID: successorID, via: Array(serverNames)))
   122→        }
   123→    }
   124→    
   125→    func stop() {
   126→        // When navigating away from the room, we need to mark the room as fully read.
   127→        // This does not affect the read receipts only the notification count.
   128→        Task { await roomProxy.markAsRead(receiptType: .fullyRead) }
   129→        // Work around QLPreviewController dismissal issues, see the InteractiveQuickLookModifier.
   130→        state.bindings.mediaPreviewViewModel = nil
   131→    }
   132→    
   133→    func timelineHasScrolled(direction: ScrollDirection) {
   134→        state.lastScrollDirection = direction
   135→    }
   136→    
   137→    func setSelectedPinnedEventID(_ eventID: String) {
   138→        state.pinnedEventsBannerState.setSelectedPinnedEventID(eventID)
   139→    }
   140→    
   141→    func displayMediaPreview(_ mediaPreviewViewModel: TimelineMediaPreviewViewModel) {
   142→        mediaPreviewViewModel.actions.sink { [weak self] action in
   143→            guard let self else { return }
   144→            switch action {
   145→            case .dismiss:
   146→                state.bindings.mediaPreviewViewModel = nil
   147→            case .displayMessageForwarding(let forwardingItem):
   148→                state.bindings.mediaPreviewViewModel = nil
   149→                // We need a small delay because we need to wait for the media preview to be fully dismissed.
   150→                DispatchQueue.main.asyncAfter(deadline: .now() + TimelineMediaPreviewViewModel.displayMessageForwardingDelay) {
   151→                    self.actionsSubject.send(.displayMessageForwarding(forwardingItem))
   152→                }
   153→            case .viewInRoomTimeline:
   154→                fatalError("\(action) should not be visible on a room preview.")
   155→            }
   156→        }
   157→        .store(in: &cancellables)
   158→        
   159→        state.bindings.mediaPreviewViewModel = mediaPreviewViewModel
   160→    }
   161→    
   162→    // MARK: - Private
   163→    
   164→    private func setupSubscriptions(ongoingCallRoomIDPublisher: CurrentValuePublisher<String?, Never>) {
   165→        appSettings.$knockingEnabled
   166→            .weakAssign(to: \.state.isKnockingEnabled, on: self)
   167→            .store(in: &cancellables)
   168→                
   169→        roomProxy.infoPublisher
   170→            .receive(on: DispatchQueue.main)
   171→            .sink { [weak self] roomInfo in
   172→                self?.updateRoomInfo(roomInfo)
   173→            }
   174→            .store(in: &cancellables)
   175→        
   176→        let identityStatusChangesPublisher = roomProxy.identityStatusChangesPublisher.receive(on: DispatchQueue.main)
   177→        
   178→        Task { [weak self] in
   179→            for await changes in identityStatusChangesPublisher.values {
   180→                guard !Task.isCancelled else {
   181→                    return
   182→                }
   183→                
   184→                await self?.processIdentityStatusChanges(changes)
   185→                await self?.updateVerificationBadge()
   186→            }
   187→        }
   188→        .store(in: &cancellables)
   189→        
   190→        clientProxy.homeserverReachabilityPublisher
   191→            .filter { $0 == .reachable }
   192→            .receive(on: DispatchQueue.main)
   193→            .sink { [weak self] _ in
   194→                self?.setupPinnedEventsTimelineItemProviderIfNeeded()
   195→            }
   196→            .store(in: &cancellables)
   197→        
   198→        ongoingCallRoomIDPublisher
   199→            .receive(on: DispatchQueue.main)
   200→            .sink { [weak self] ongoingCallRoomID in
   201→                guard let self else { return }
   202→                state.isParticipatingInOngoingCall = ongoingCallRoomID == roomProxy.id
   203→            }
   204→            .store(in: &cancellables)
   205→        
   206→        roomProxy.knockRequestsStatePublisher
   207→            // We only care about unseen requests
   208→            .map { knockRequestsState in
   209→                guard case let .loaded(requests) = knockRequestsState else {
   210→                    return []
   211→                }
   212→                
   213→                return requests
   214→                    .filter { !$0.isSeen }
   215→                    .map(KnockRequestInfo.init)
   216→            }
   217→            // If the requests have the same event ids we can discard the output
   218→            .removeDuplicates { Set($0.map(\.eventID)) == Set($1.map(\.eventID)) }
   219→            .throttle(for: .milliseconds(100), scheduler: DispatchQueue.main, latest: true)
   220→            .weakAssign(to: \.state.unseenKnockRequests, on: self)
   221→            .store(in: &cancellables)
   222→        
   223→        NotificationCenter.default.publisher(for: UIApplication.didBecomeActiveNotification)
   224→            .sink { [weak self] _ in
   225→                self?.roomProxy.timeline.retryDecryption(sessionIDs: nil)
   226→            }
   227→            .store(in: &cancellables)
   228→    }
   229→    
   230→    private func processIdentityStatusChanges(_ changes: [IdentityStatusChange]) async {
   231→        for change in changes {
   232→            switch change.changedTo {
   233→            case .pinViolation:
   234→                guard case let .success(member) = await roomProxy.getMember(userID: change.userId) else {
   235→                    MXLog.error("Failed retrieving room member for identity status change: \(change)")
   236→                    continue
   237→                }
   238→                
   239→                identityPinningViolations[change.userId] = member
   240→            case .verificationViolation:
   241→                guard case let .success(member) = await roomProxy.getMember(userID: change.userId) else {
   242→                    MXLog.error("Failed retrieving room member for identity status change: \(change)")
   243→                    continue
   244→                }
   245→
   246→                identityVerificationViolations[change.userId] = member
   247→            default:
   248→                identityVerificationViolations[change.userId] = nil
   249→                identityPinningViolations[change.userId] = nil
   250→            }
   251→        }
   252→        
   253→        if let member = identityVerificationViolations.values.first {
   254→            state.footerDetails = .verificationViolation(member: member,
   255→                                                         learnMoreURL: appSettings.identityPinningViolationDetailsURL)
   256→        } else if let member = identityPinningViolations.values.first {
   257→            state.footerDetails = .pinViolation(member: member,
   258→                                                learnMoreURL: appSettings.identityPinningViolationDetailsURL)
   259→        } else {
   260→            state.footerDetails = nil
   261→        }
   262→    }
   263→    
   264→    private func updateVerificationBadge() async {
   265→        guard roomProxy.isDirectOneToOneRoom,
   266→              let dmRecipient = roomProxy.membersPublisher.value.first(where: { $0.userID != roomProxy.ownUserID }),
   267→              case let .success(userIdentity) = await clientProxy.userIdentity(for: dmRecipient.userID, fallBackToServer: true) else {
   268→            state.dmRecipientVerificationState = .notVerified
   269→            return
   270→        }
   271→        
   272→        guard let userIdentity else {
   273→            MXLog.failure("User identity should be known at this point")
   274→            state.dmRecipientVerificationState = .notVerified
   275→            return
   276→        }
   277→        
   278→        state.dmRecipientVerificationState = userIdentity.verificationState
   279→    }
   280→    
   281→    private func resolveIdentityPinningViolation(_ userID: String) async {
   282→        defer {
   283→            hideLoadingIndicator()
   284→        }
   285→        
   286→        showLoadingIndicator()
   287→        
   288→        if case .failure = await clientProxy.pinUserIdentity(userID) {
   289→            state.bindings.alertInfo = .init(id: .unknown, title: L10n.commonError)
   290→        }
   291→    }
   292→    
   293→    private func resolveIdentityVerificationViolation(_ userID: String) async {
   294→        defer {
   295→            hideLoadingIndicator()
   296→        }
   297→
   298→        showLoadingIndicator()
   299→
   300→        if case .failure = await clientProxy.withdrawUserIdentityVerification(userID) {
   301→            state.bindings.alertInfo = .init(id: .unknown, title: L10n.commonError)
   302→        }
   303→    }
   304→    
   305→    private func buildPinnedEventContents(timelineItems: [TimelineItemProxy]) {
   306→        var pinnedEventContents = OrderedDictionary<String, AttributedString>()
   307→        
   308→        for item in timelineItems {
   309→            // Only remote events are pinned
   310→            if case let .event(event) = item,
   311→               let eventID = event.id.eventID {
   312→                pinnedEventContents.updateValue(pinnedEventStringBuilder.buildAttributedString(for: event) ?? AttributedString(L10n.commonUnsupportedEvent),
   313→                                                forKey: eventID)
   314→            }
   315→        }
   316→        
   317→        state.pinnedEventsBannerState.setPinnedEventContents(pinnedEventContents)
   318→        
   319→        // If it's the first time we are setting the pinned events, we should select the initial event if available.
   320→        if let initialSelectedPinnedEventID {
   321→            state.pinnedEventsBannerState.setSelectedPinnedEventID(initialSelectedPinnedEventID)
   322→            self.initialSelectedPinnedEventID = nil
   323→        }
   324→    }
   325→    
   326→    private func updateRoomInfo(_ roomInfo: RoomInfoProxyProtocol) {
   327→        state.roomTitle = roomInfo.displayName ?? roomProxy.id
   328→        state.roomAvatar = roomInfo.avatar
   329→        state.hasOngoingCall = roomInfo.hasRoomCall
   330→        state.hasSuccessor = roomInfo.successor != nil
   331→        
   332→        let pinnedEventIDs = roomInfo.pinnedEventIDs
   333→        // Only update the loading state of the banner
   334→        if state.pinnedEventsBannerState.isLoading {
   335→            state.pinnedEventsBannerState = .loading(numbersOfEvents: pinnedEventIDs.count)
   336→        }
   337→        
   338→        switch (roomProxy.isDirectOneToOneRoom, roomInfo.joinRule) {
   339→        case (false, .knock), (false, .knockRestricted):
   340→            state.isKnockableRoom = true
   341→        default:
   342→            state.isKnockableRoom = false
   343→        }
   344→
   345→        if let powerLevels = roomInfo.powerLevels {
   346→            state.canSendMessage = powerLevels.canOwnUser(sendMessage: .roomMessage)
   347→            state.canJoinCall = powerLevels.canOwnUserJoinCall()
   348→            state.canAcceptKnocks = powerLevels.canOwnUserInvite()
   349→            state.canDeclineKnocks = powerLevels.canOwnUserKick()
   350→            state.canBan = powerLevels.canOwnUserBan()
   351→        }
   352→        
   353→        // This causes the UI to become inconsistent with the user's mental model if the user
   354→        // does not restart the app after disabling the feature flag. We can probably ignore
   355→        // such cases, since we explicitly ask for an app restart in the caption of the feature
   356→        // flag switch.
   357→        if appSettings.enableKeyShareOnInvite {
   358→            state.roomHistorySharingState = roomInfo.historySharingState
   359→        }
   360→    }
   361→    
   362→    private func setupPinnedEventsTimelineItemProviderIfNeeded() {
   363→        guard pinnedEventsTimelineItemProvider == nil else {
   364→            return
   365→        }
   366→        
   367→        Task {
   368→            guard case let .success(pinnedEventsTimeline) = await roomProxy.pinnedEventsTimeline() else {
   369→                return
   370→            }
   371→            
   372→            if pinnedEventsTimelineItemProvider == nil {
   373→                pinnedEventsTimelineItemProvider = pinnedEventsTimeline.timelineItemProvider
   374→            }
   375→        }
   376→    }
   377→        
   378→    private func acceptKnock(eventID: String) async {
   379→        guard case let .loaded(requests) = roomProxy.knockRequestsStatePublisher.value,
   380→              let request = requests.first(where: { $0.eventID == eventID }) else {
   381→            return
   382→        }
   383→        
   384→        state.handledEventIDs.insert(eventID)
   385→        switch await request.accept() {
   386→        case .success:
   387→            break
   388→        case .failure:
   389→            userIndicatorController.submitIndicator(.init(id: Self.errorIndicatorIdentifier, type: .toast, title: L10n.errorUnknown))
   390→            state.handledEventIDs.remove(eventID)
   391→        }
   392→    }
   393→    
   394→    private func markAllKnocksAsSeen() async {
   395→        guard case let .loaded(requests) = roomProxy.knockRequestsStatePublisher.value else {
   396→            return
   397→        }
   398→        state.handledEventIDs.formUnion(Set(requests.map(\.eventID)))
   399→        
   400→        let failedIDs = await withTaskGroup(of: (String, Result<Void, KnockRequestProxyError>).self) { group in
   401→            for request in requests {
   402→                group.addTask {
   403→                    await (request.eventID, request.markAsSeen())
   404→                }
   405→            }
   406→            
   407→            var failedIDs = [String]()
   408→            for await result in group where result.1.isFailure {
   409→                failedIDs.append(result.0)
   410→            }
   411→            return failedIDs
   412→        }
   413→        state.handledEventIDs.subtract(failedIDs)
   414→    }
   415→    
   416→    private func handleTappedPinnedEventsBanner() {
   417→        analyticsService.trackInteraction(name: .PinnedMessageBannerClick)
   418→        if let eventID = state.pinnedEventsBannerState.selectedPinnedEventID {
   419→            Task {
   420→                switch await roomProxy.loadOrFetchEventDetails(for: eventID) {
   421→                case .success(let event):
   422→                    if appSettings.threadsEnabled,
   423→                       let threadRootEventID = event.threadRootEventId() {
   424→                        actionsSubject.send(.focusEvent(eventID: threadRootEventID))
   425→                        actionsSubject.send(.displayThread(threadRootEventID: threadRootEventID, focussedEventID: eventID))
   426→                    } else {
   427→                        actionsSubject.send(.focusEvent(eventID: eventID))
   428→                    }
   429→                case .failure:
   430→                    userIndicatorController.submitIndicator(.init(title: L10n.errorUnknown))
   431→                }
   432→            }
   433→        }
   434→        state.pinnedEventsBannerState.previousPin()
   435→    }
